WITH unpacked AS (SELECT id, created_at, ship_to, attributes, ship_to.country AS ship_country, SIZE(attributes) AS num_attributes, AGGREGATE(items, 0D, (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS cart_value, TRANSFORM(FILTER(items, li -> li.promo IS NOT NULL), li -> STRUCT(li.product_id AS pid, ROUND(li.price * 0.9, 2) AS discounted_price)) AS promo_lines FROM carts WHERE TO_DATE(created_at) >= '2025-01-14') SELECT id, ship_country, num_attributes, cart_value, LEAD(cart_value) OVER (PARTITION BY ship_country ORDER BY num_attributes, id) next_cart_value, LAG(cart_value) OVER (PARTITION BY ship_country ORDER BY num_attributes, id) prev_cart_value, LEAD(num_attributes) OVER (PARTITION BY ship_country ORDER BY num_attributes, id) next_num_attributes, ROW_NUMBER() OVER (PARTITION BY ship_country ORDER BY num_attributes, id) row_seq FROM unpacked WHERE HOUR(created_at) BETWEEN 6 AND 13;
